insert into public.supplier_profiles(supplier_id,slug,website,address,founded_year,verified_at,profile_data,updated_at)
select supplier_id,slug,website,address,founded_year,verified_at,profile_data,now()
from source_rows
on conflict(supplier_id) do update set slug=excluded.slug,website=excluded.website,address=excluded.address,
 founded_year=excluded.founded_year,verified_at=excluded.verified_at,profile_data=excluded.profile_data,updated_at=now();

